"""Copy History into the new development project with both apps closed."""
from contextlib import closing
import hashlib
import json
from pathlib import Path
import sqlite3
import time


def fingerprint(path):
    value = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b""):
            value.update(chunk)
    return value.digest()


def contents(db):
    value = hashlib.sha256()
    for row in db.execute("SELECT * FROM results ORDER BY sequence"):
        value.update(repr(row).encode("utf-8") + b"\n")
    return value.digest()


def copy_history(source, destination):
    source, destination = Path(source).absolute(), Path(destination).absolute()
    for path in (source, destination):
        for parent in (path, *path.parents):
            if parent.is_symlink() or parent.is_junction():
                raise ValueError("Linked folder")
    source, destination = source.resolve(), destination.resolve()
    if source == destination or source in destination.parents or destination in source.parents:
        raise ValueError("Overlapping folders")
    state = source / "output/desktop-state.json"
    copied_state = destination / "output/desktop-state.json"
    history = source / "output/history.sqlite3"
    target = destination / "output/history.sqlite3"
    paths = (state, copied_state, history, target)
    for path in paths:
        for parent in (path, *path.parents):
            if parent.is_symlink() or parent.is_junction():
                raise ValueError("Linked path")
    if target.exists() or any(Path(str(target) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")):
        raise FileExistsError("Destination History already exists")
    settings = json.loads(state.read_text(encoding="utf-8"))
    name = settings.get("history_path", "output/history.sqlite3")
    if not isinstance(name, str) or Path(name).is_absolute() or Path(name) != Path("output/history.sqlite3"):
        raise ValueError("Nondefault History path; separate review required")
    if fingerprint(state) != fingerprint(copied_state):
        raise ValueError("Saved settings copies differ")
    before = {p: fingerprint(p) for p in (state, copied_state, history)}
    with closing(sqlite3.connect(history.as_uri() + "?mode=ro", uri=True)) as old:
        old.execute("BEGIN")
        if old.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
            raise ValueError("Source integrity")
        expected = contents(old)
        version = old.execute("PRAGMA user_version").fetchone()
        with target.open("xb"):
            pass
        deadline = time.monotonic() + 60
        def progress(status, remaining, total):
            if time.monotonic() > deadline:
                raise TimeoutError("Copy timed out")
        with closing(sqlite3.connect(target)) as new:
            old.backup(new, pages=256, progress=progress)
            if new.execute("PRAGMA integrity_check").fetchall() != [("ok",)]:
                raise ValueError("Copy integrity")
            if contents(new) != expected or new.execute("PRAGMA user_version").fetchone() != version:
                raise ValueError("Copy contents")
    if any(fingerprint(path) != expected for path, expected in before.items()):
        raise ValueError("Files changed during copy")


def main():
    source = Path(__file__).absolute().parent
    try:
        copy_history(source, source.parent / "Development" / "AppHealthChecker")
    except Exception as exc:
        print("HISTORY COPY STOPPED:", type(exc).__name__)
        print("Do not retry or delete files; report this status.")
        return
    print("HISTORY COPY: PASS")
    print("DATABASE INTEGRITY / CONTENTS: PASS")
    print("SOURCE HISTORY / SAVED SETTINGS: UNCHANGED")


if __name__ == "__main__":
    main()
